// -----------------------------------------------------------------------------
// tb_fi.v - fault-injection campaign testbench (V0, or V1 with -DV1).
//           Also V1-P (-DV1P, pipelined checker) and V2 (-DV2, two checkers);
//           the drain variants use tb/tb_fi_d.v.
//
// No hooks in the RTL: faults are applied from here with force / release and
// by depositing values into registers through hierarchical references. The
// case statements that name every site are generated by fi/sites.py into
// sim/fi/fi_sites_<cfg>.vh and included below (compile with -I sim/fi and
// -DFI_SITES=\"fi_sites_<cfg>.vh\").
//
// Plusargs:
//   +vec=<dir>     matrices + golden C (scripts/golden.py format)
//   +faults=<file> one injection per line: "fid site mode cycle mat"
//                  mode 0 = none (golden run), 1 = stuck-at-0, 2 = stuck-at-1,
//                  3 = held-inverted (persistent), 4 = 1-cycle flip at `cycle`
//                  persistent modes (1-3) are active for the WHOLE run
//   +out=<file>    one result line per injection
//   +vcd=<file>    optional waveform (use with a short fault list)
//
// Run cycle numbering: rc = 0 is the cycle after start is sampled (the CLEAR
// cycle in a fault-free run), stream = 1..K, done = K+2N-1 in a fault-free run.
//
// Result line: fid site mode cycle mat correct n_wrong alarm hang done_rc mask chk_fault
//   correct = every C element equals golden when done is first seen
//   alarm   = V1 alarm one cycle after done (V0: always 0); V1-P: three
//             cycles after done (its checker needs 2 more cycles); V2: both
//             checkers agree
//   chk_fault = V2 only: the two checkers disagree (else 0)
//   hang    = done never came within the timeout (output counted as wrong)
//   mask    = hex bitmask of wrong C elements, bit i*N+j = C[i][j]
//
// The producer model: on every cycle with in_ready = 1 it streams the next
// column/row (up to K of them); on every other cycle it drives zeros.
// -----------------------------------------------------------------------------

`timescale 1ns / 1ps

`ifdef V2
  `define ATOP dut.u_top
  `define CHK1 dut.u_chk1
  `define CHK2 dut.u_chk2
  `define TOP  dut
`elsif V1P
  `define ATOP dut.u_top
  `define CHK  dut.u_chk
`elsif V1
  `define ATOP dut.u_top
  `define CHK  dut.u_chk
`else
  `define ATOP dut
  `define CHK  dut
`endif

module tb_fi;

    parameter N          = 4;
    parameter K          = 4;
    parameter DATA_WIDTH = 8;
    parameter ACC_WIDTH  = 32;
    parameter MAXT       = 16;            // matrices in the vector file

    localparam TIMEOUT = 2*(K + 2*N) + 8;
`ifdef V1P
    localparam POST = 2;                 // extra cycles the pipelined checker needs
`else
    localparam POST = 0;
`endif

    reg clk = 1'b0;
    always #5 clk = ~clk;

    reg                          rst_n;
    reg                          start;
    reg  [N*DATA_WIDTH-1:0]      a_col;
    reg  [N*DATA_WIDTH-1:0]      b_row;
    wire                         in_ready;
    wire                         busy;
    wire                         done;
    wire [N*N*ACC_WIDTH-1:0]     c_flat;
    wire                         alarm;
    wire                         chk_fault;

`ifdef V2
    labft_top_2 #(.N(N), .K(K), .DATA_WIDTH(DATA_WIDTH), .ACC_WIDTH(ACC_WIDTH)) dut (
        .clk(clk), .rst_n(rst_n), .start(start), .a_col(a_col), .b_row(b_row),
        .in_ready(in_ready), .busy(busy), .done(done), .c_flat(c_flat), .alarm(alarm),
        .chk_fault(chk_fault));
`elsif V1P
    labft_top_p #(.N(N), .K(K), .DATA_WIDTH(DATA_WIDTH), .ACC_WIDTH(ACC_WIDTH)) dut (
        .clk(clk), .rst_n(rst_n), .start(start), .a_col(a_col), .b_row(b_row),
        .in_ready(in_ready), .busy(busy), .done(done), .c_flat(c_flat), .alarm(alarm));
    assign chk_fault = 1'b0;
`elsif V1
    labft_top #(.N(N), .K(K), .DATA_WIDTH(DATA_WIDTH), .ACC_WIDTH(ACC_WIDTH)) dut (
        .clk(clk), .rst_n(rst_n), .start(start), .a_col(a_col), .b_row(b_row),
        .in_ready(in_ready), .busy(busy), .done(done), .c_flat(c_flat), .alarm(alarm));
    assign chk_fault = 1'b0;
`else
    array_top #(.N(N), .K(K), .DATA_WIDTH(DATA_WIDTH), .ACC_WIDTH(ACC_WIDTH)) dut (
        .clk(clk), .rst_n(rst_n), .start(start), .a_col(a_col), .b_row(b_row),
        .in_ready(in_ready), .clear_o(), .busy(busy), .done(done), .c_flat(c_flat));
    assign alarm = 1'b0;
    assign chk_fault = 1'b0;
`endif

    `include `FI_SITES

    reg [N*DATA_WIDTH-1:0] amem [0:MAXT*K-1];
    reg [N*DATA_WIDTH-1:0] bmem [0:MAXT*K-1];
    reg [ACC_WIDTH-1:0]    cmem [0:MAXT*N*N-1];

    reg [8*512-1:0] vecdir, faultfile, outfile, vcdfile;
    integer fin, fout, nread, nrun;
    integer fid, site, mode, fcyc, mat;
    integer rc, t, ii, nwrong, done_rc, got_done, hang, alarm_s, chkf_s, p;
    reg     inv_on;
    reg [N*N-1:0] mask;
    reg [N*N*ACC_WIDTH-1:0] c_at_done;
    reg     dumpc;

    // held-inverted: the register's output is the inverse of what it stores.
    // Re-inverting right after every clock edge gives exactly that behaviour
    // (the logic always reads the inverted value, including in feedback loops).
    always @(posedge clk) begin
        if (inv_on) begin
            #1;
            fi_flip(site);
        end
    end

    // producer: stream K columns/rows on in_ready cycles, zeros otherwise
    task drive_inputs;
        begin
            if (in_ready && t < K) begin
                a_col = amem[mat*K + t];
                b_row = bmem[mat*K + t];
                t = t + 1;
            end else begin
                a_col = {N*DATA_WIDTH{1'b0}};
                b_row = {N*DATA_WIDTH{1'b0}};
            end
        end
    endtask

    task compare_c;
        begin
            nwrong = 0;
            mask = {N*N{1'b0}};
            for (ii = 0; ii < N*N; ii = ii + 1) begin
                if (c_flat[ii*ACC_WIDTH +: ACC_WIDTH] !== cmem[mat*N*N + ii]) begin
                    nwrong = nwrong + 1;
                    mask[ii] = 1'b1;
                end
            end
        end
    endtask

    task run_one;
        begin
            // clean reset (all forces were released at the end of the last run)
            inv_on = 1'b0;
            rst_n  = 1'b0;
            start  = 1'b0;
            t      = 0;
            a_col  = {N*DATA_WIDTH{1'b0}};
            b_row  = {N*DATA_WIDTH{1'b0}};
            @(negedge clk);
            rst_n = 1'b1;

            // persistent fault: installed before the multiply starts
            if (mode == 1) fi_force(site, 1'b0);
            if (mode == 2) fi_force(site, 1'b1);
            if (mode == 3) begin
                fi_flip(site);       // stored 0 after reset -> output reads 1
                inv_on = 1'b1;
            end

            start = 1'b1;
            @(negedge clk);          // now in rc = 0
            start = 1'b0;
            rc = 0;
            got_done = 0;
            hang = 0;
            done_rc = -1;
            while (!got_done && !hang) begin
                // 1-cycle transient flip in cycle rc == fcyc
                if (mode == 4 && rc == fcyc) fi_flip(site);
                if (mode == 4 && rc == fcyc + 1 && fi_is_net(site)) fi_release(site);
                drive_inputs;
                if (done) begin
                    got_done = 1;
                    done_rc = rc;
                    compare_c;
                    c_at_done = c_flat;
                end else if (rc >= TIMEOUT) begin
                    hang = 1;
                    compare_c;
                    if (nwrong == 0) nwrong = -1;   // no result delivered
                end
                if (!got_done && !hang) begin
                    @(negedge clk);
                    rc = rc + 1;
                end
            end
            // V1-P only: the checker needs POST more cycles; a 1-cycle flip
            // may still land in them
            for (p = 0; p < POST; p = p + 1) begin
                @(negedge clk);
                rc = rc + 1;
                if (mode == 4 && rc == fcyc) fi_flip(site);
                if (mode == 4 && rc == fcyc + 1 && fi_is_net(site)) fi_release(site);
            end
            // alarm latches on the edge that ends the done cycle (+POST)
            @(negedge clk);
            alarm_s = alarm;
            chkf_s  = chk_fault;
            // remove the fault
            inv_on = 1'b0;
            if (mode == 1 || mode == 2 || (mode == 4 && fi_is_net(site))) fi_release(site);
            $fdisplay(fout, "%0d %0d %0d %0d %0d %0d %0d %0d %0d %0d %h %0d",
                      fid, site, mode, fcyc, mat, (nwrong == 0 && !hang), nwrong,
                      alarm_s, hang, done_rc, mask, chkf_s);
            // +dumpc: also print every C element as seen at done (for hand checks)
            if (dumpc)
                for (ii = 0; ii < N*N; ii = ii + 1)
                    $fdisplay(fout, "C %0d %0d %0d", fid, ii, $signed(c_at_done[ii*ACC_WIDTH +: ACC_WIDTH]));
        end
    endtask

    initial begin
        if (!$value$plusargs("vec=%s", vecdir) || !$value$plusargs("faults=%s", faultfile) ||
            !$value$plusargs("out=%s", outfile)) begin
            $display("FATAL: need +vec= +faults= +out=");
            $finish;
        end
        if ($value$plusargs("vcd=%s", vcdfile)) begin
            $dumpfile(vcdfile);
            $dumpvars(0, tb_fi);
        end
        $readmemh({vecdir, "/a.hex"}, amem);
        $readmemh({vecdir, "/b.hex"}, bmem);
        $readmemh({vecdir, "/c.hex"}, cmem);
        dumpc = $test$plusargs("dumpc");
        fin  = $fopen(faultfile, "r");
        fout = $fopen(outfile, "w");
        inv_on = 1'b0;
        site = -1;
        nrun = 0;
        nread = $fscanf(fin, "%d %d %d %d %d\n", fid, site, mode, fcyc, mat);
        while (nread == 5) begin
            run_one;
            nrun = nrun + 1;
            nread = $fscanf(fin, "%d %d %d %d %d\n", fid, site, mode, fcyc, mat);
        end
        $fclose(fout);
        $display("FI_DONE runs=%0d", nrun);
        $finish;
    end

endmodule
